theorem ProgramProgress.map {p : PFunctor.{u, u}} {source target : Type u}
    {program : FreeM p source} (progress : ProgramProgress program)
    (function : source → target) : ProgramProgress (FreeM.map function program)

theorem intro {realization : Realization bd}
    {program : (n : ℕ) → input n → FreeM (p n) (output n)}
    (implementation : ∀ n, (realization.machine n).ImplementsWithin
      (program n) (realization.rounds.eval n)) :
    realization.Implements program

theorem apply {realization : Realization bd}
    {program : (n : ℕ) → input n → FreeM (p n) (output n)}
    (implementation : realization.Implements program) (n : ℕ) :
    (realization.machine n).ImplementsWithin
      (program n) (realization.rounds.eval n)

@[simp] theorem cost_eq_time_envelope {source target : Type u}
    {sourceEncoding : source → List Bool} {targetEncoding : target → List Bool}
    {function : source → target}
    (code : EncPolyTime sourceEncoding targetEncoding function) (input : source) :
    quantitative.cost code input = code.time.eval (sourceEncoding input).length

theorem lensMapComp
    {P₁ : PFunctor.{uA₁, uB}} {Q₁ : PFunctor.{uA₂, uB}}
    {P₂ : PFunctor.{uA₃, uB}} {Q₂ : PFunctor.{uA₄, uB}}
    {P₃ : PFunctor.{uA₅, uB}} {Q₃ : PFunctor.{uA₆, uB}}
    (firstLeft : Lens P₁ P₂) (firstRight : Lens Q₁ Q₂)
    (secondLeft : Lens P₂ P₃) (secondRight : Lens Q₂ Q₃) :
    Lens.parallelSumMap secondLeft secondRight ∘ₗ
        Lens.parallelSumMap firstLeft firstRight =
      Lens.parallelSumMap (secondLeft ∘ₗ firstLeft)
        (secondRight ∘ₗ firstRight)

theorem lensCanary {p : PFunctor.{uA, uB}} {q : PFunctor.{uA₂, uB₂}}
    {β : Type uβ} (lens : Lens p q) (computation : Resumption p β) :
    toITree (mapLens lens computation) = ITree.mapSpec lens (toITree computation)

theorem traceWork_unitCost {p : PFunctor.{0, 0}} [DecidableEq p.A]
    {input output : Type} {bd : Boundary StepClass.unconstrained.{0, 0} p input output}
    {R : QuantitativeRealization unitCostBackend bd} {start finish : R.machine.State}
    (trace : R.ExecutionTrace start finish) : trace.cost.work = 2 * trace.length

theorem traceTraffic_unitCost {p : PFunctor.{0, 0}} [DecidableEq p.A]
    {input output : Type} {bd : Boundary StepClass.unconstrained.{0, 0} p input output}
    {R : QuantitativeRealization unitCostBackend bd} {start finish : R.machine.State}
    (trace : R.ExecutionTrace start finish) : trace.cost.traffic = 2 * trace.length

theorem tracePeakState_unitCost {p : PFunctor.{0, 0}} [DecidableEq p.A]
    {input output : Type} {bd : Boundary StepClass.unconstrained.{0, 0} p input output}
    {R : QuantitativeRealization unitCostBackend bd} {start finish : R.machine.State}
    (trace : R.ExecutionTrace start finish) : trace.cost.peakStateSize ≤ 1

theorem tracePeakHead_unitCost {p : PFunctor.{0, 0}} [DecidableEq p.A]
    {input output : Type} {bd : Boundary StepClass.unconstrained.{0, 0} p input output}
    {R : QuantitativeRealization unitCostBackend bd} {start finish : R.machine.State}
    (trace : R.ExecutionTrace start finish) : trace.cost.peakHeadSize ≤ 1

theorem executionCost_unitCost {p : PFunctor.{0, 0}} [DecidableEq p.A]
    {input output : Type} {bd : Boundary StepClass.unconstrained.{0, 0} p input output}
    {R : QuantitativeRealization unitCostBackend bd} (inputValue : input)
    {finish : R.machine.State}
    (trace : R.ExecutionTrace (R.machine.init inputValue) finish) :
    R.executionCost inputValue trace = unitCostEnvelope trace.length

private theorem polynomialHandoff_eval (model : queryContract.Model) (input : PUnit) :
    polynomialHandoff.polynomial.eval model.modulus
      (queryBackend.size queryBoundary.input input) = handoffPolynomialBound

theorem terminationSemanticsUniverseCanary {p : PFunctor.{uA, uB}}
    {α : Type uInput} {β : Type uOutput}
    (M : DynComputation.{uState} p α β) (state : M.State)
    (termination : M.TerminatesFrom state) :
    M.toDynSystem.behavior state =
      FreeM.toResumption (terminationUniverseCanary M state termination)

@[simp] theorem Hom.comp_toLens {C D E : Comonoid.{uA, uB}}
    (f : Hom C D) (g : Hom D E) :
    (f.comp g).toLens = g.toLens ∘ₗ f.toLens

theorem Hom.comp_assoc {C D E F : Comonoid.{uA, uB}}
    (f : Hom C D) (g : Hom D E) (h : Hom E F) :
    (f.comp g).comp h = f.comp (g.comp h)

@[simp] theorem mapTarget_id {m : Type u → Type v}
    {q : PFunctor.{uA, u}} (handler : PFunctor.Handler m q) :
    mapTarget (fun computation => computation) handler = handler

@[simp]
theorem sigma_apply {I : Type uI} {P : I → PFunctor.{uA, u}} {m : Type u → Type v}
    (f : (i : I) → PFunctor.Handler m (P i)) (i : I) (a : (P i).A) : sigma f ⟨i, a⟩ = f i a

lemma eqRec_id_apply {α : Sort u} {β : α → Sort v}
    {a1 a0 : α} (h : a1 = a0) (x : β a0) :
    Eq.rec (motive := fun y _ => β y → β a1) id h x = _root_.cast (congrArg β h).symm x

