@[simp] theorem Hom.comp_toLens {M N O : SubstMonoid.{uA, uB}}
    (f : Hom M N) (g : Hom N O) :
    (f.comp g).toLens = g.toLens ∘ₗ f.toLens

theorem Hom.comp_assoc {M N O P : SubstMonoid.{uA, uB}}
    (f : Hom M N) (g : Hom N O) (h : Hom O P) :
    (f.comp g).comp h = f.comp (g.comp h)

lemma run_liftBind_of_cons {a : P.A} (next : P.B a → FreeM P α) {s : Supply P} {u : P.B a}
    {us : List (P.B a)} (hs : s a = u :: us) :
    run (FreeM.liftBind a next) s = run (next u) (s.update a us)

private lemma addValues_update_of_ne (s : Supply P) {a b : P.A} (hb : b ≠ a)
    (vs : List (P.B b)) (us : List (P.B a)) :
    (s.addValues us).update b vs = (s.update b vs).addValues us

theorem run_setAt_eq_run_takeAt_addValues (program : FreeM P α) (s : Supply P) (a : P.A) {n : ℕ}
    (u : P.B a) (hn : n < (s a).length) {x : α} {s' : Supply P}
    (h : run program ((s.takeAt a n).addValues [u]) = some (x, s')) :
    run program (s.setAt a n u) = some (x, s'.addValues ((s a).drop (n + 1)))

theorem mapPartial_mul {P : PFunctor.{uA₁, uB₁}} {Q : PFunctor.{uA₂, uB₂}}
    (f : Idx P → Option (Idx Q)) (a b : TraceList P) :
    mapPartial f (a * b) = mapPartial f a * mapPartial f b

private lemma transported_dependent_apply {ι : Type u} {γ : Type v} (F : ι → Type w) {a b : ι}
    (h : a = b) (f : F a → γ) (x : F a) (y : F b) (hy : cast (congrArg F h) x = y) :
    Eq.rec (motive := fun b (_ : a = b) => F b → γ) f h y = f x

private lemma cast_exp_direction_of_inl {q r : PFunctor.{uA, uB}} {f f' : (exp r q).A} (h : f = f')
    {i : q.A} {d : r.B (f i).1} {d' : r.B (f' i).1} {bd : (y + C (q.B i)).B ((f i).2 d)}
    {bd' : (y + C (q.B i)).B ((f' i).2 d')} (hd : d ≍ d') (hb : (f i).2 d = Sum.inl PUnit.unit) :
    cast (congrArg (exp r q).B h) ⟨i, d, bd⟩ = ⟨i, d', bd'⟩

private lemma exp_direction_components {q r : PFunctor} {f f' : (exp r q).A}
    (h : f = f') {x : (exp r q).B f} {y : (exp r q).B f'} (hy : x ≍ y) :
    x.1 = y.1 ∧ x.2.1 ≍ y.2.1

lemma isRollBound_congr
    {oa : FreeM P α} {b : B}
    {canRoll₁ canRoll₂ : P.A → B → Prop} {cost₁ cost₂ : P.A → B → B}
    (hcan : ∀ (a : P.A) (b : B), canRoll₁ a b ↔ canRoll₂ a b)
    (hcost : ∀ (a : P.A) (b : B), cost₁ a b = cost₂ a b) :
    oa.IsRollBound b canRoll₁ cost₁ ↔ oa.IsRollBound b canRoll₂ cost₂

lemma IsRollBound.proj
    {B' : Type*} (proj : B → B')
    {oa : FreeM P α} {b : B}
    {canRoll : P.A → B → Prop} {cost : P.A → B → B}
    {canRoll' : P.A → B' → Prop} {cost' : P.A → B' → B'}
    (h_can : ∀ (a : P.A) (b' : B), canRoll a b' → canRoll' a (proj b'))
    (h_cost : ∀ (a : P.A) (b' : B), canRoll a b' → proj (cost a b') = cost' a (proj b'))
    (h : IsRollBound oa b canRoll cost) :
    IsRollBound oa (proj b) canRoll' cost'

lemma IsTotalRollBound.mono {oa : FreeM P α} {n₁ n₂ : ℕ}
    (h : IsTotalRollBound oa n₁) (hle : n₁ ≤ n₂) :
    IsTotalRollBound oa n₂

private theorem corec_bindStep_inr (k : α → Resumption p β)
    (computation : Resumption p β) :
    corec (bindStep k) (Sum.inr computation) = computation

theorem shape'_corec_eq {S : Type uS} {shape : (ViewPoly F α).A}
    {children : (ViewPoly F α).B shape → S}
    (next : S → (ViewPoly F α).Obj S) (seed : S)
    (h : next seed = ⟨shape, children⟩) :
    shape' (corec next seed) = ⟨shape, fun direction => corec next (children direction)⟩

theorem eq_pure_of_dest {t : ITree F α} {r : α}
    {c : (ViewPoly F α).B (.pure r) → ITree F α}
    (h : shape' t = ⟨.pure r, c⟩) : t = pure r

theorem eq_query_of_dest {t : ITree F α} {a : F.A}
    {c : (ViewPoly F α).B (.query a) → ITree F α}
    (h : shape' t = ⟨.query a, c⟩) : t = query a c

theorem toLTS_silentStep_of_step {t : ITree F α}
    (c : PUnit.{uFB + 1} → ITree F α) (head : shape' t = ⟨.step, c⟩) :
    (toLTS F α).SilentStep (some t) (some (c PUnit.unit))

private theorem silentSteps_from_none
    {target : Option (ITree F α)}
    (steps : (toLTS F α).SilentSteps none target) : target = none

private theorem silentSteps_from_pure (result : α)
    {target : Option (ITree F α)}
    (steps : (toLTS F α).SilentSteps (some (pure result)) target) :
    target = some (pure result)

private theorem visibleStep_from_pure (result : α)
    {observation : Observation F α} {target : Option (ITree F α)}
    (step : (toLTS F α).VisibleStep (some (pure result)) observation target) :
    observation = .ret result ∧ target = none

private theorem weakTrace_from_none_aux
    {source : Option (ITree F α)}
    {observations : List (Observation F α)}
    {target : Option (ITree F α)}
    (hsource : source = none)
    (trace : (toLTS F α).WeakTrace source observations target) :
    observations = [] ∧ target = none

private theorem weakTrace_from_none
    {observations : List (Observation F α)}
    {target : Option (ITree F α)}
    (trace : (toLTS F α).WeakTrace none observations target) :
    observations = [] ∧ target = none

private theorem weakTrace_from_pure_aux (result : α)
    {source : Option (ITree F α)}
    {observations : List (Observation F α)}
    {target : Option (ITree F α)}
    (hsource : source = some (pure result))
    (trace : (toLTS F α).WeakTrace source observations target) :
    observations = [] ∨ observations = [.ret result]

theorem TauFree.of_shape'_query {tree : _root_.ITree p β} {position : p.A}
    {next : p.B position → _root_.ITree p β} (hshape : shape' tree = ⟨.query position, next⟩)
    (h : TauFree tree) : ∀ direction, TauFree (next direction)

theorem mk_heq {α : Type u} {β β' : Type v}
    {a : α} {b : β} {b' : β'} (h : b ≍ b') :
    ((a, b) : α × β) ≍ ((a, b') : α × β')

theorem isRealizableBy_unconstrained (system : DynSystem State p) :
    IsRealizableBy StepClass.unconstrained.{u, v}
      (Boundary.unconstrained p) system

theorem isRealizableBy_unconstrained [DecidableEq p.A] (program : α → FreeM p β) :
    IsRealizableBy StepClass.unconstrained.{u, v}
      (Boundary.unconstrained p α β) program

theorem IsRealizableBy.ulift_wrapChoiceProd
    {p q r : PFunctor.{uA, uB}} {S T : Type uS}
    {C : StepClass.{max uS uA uB, v}} [P : C.HasProd] [Su : C.HasSum]
    [O : C.HasOption] [C.IsDistributive]
    [U : C.HasULiftProd.{uS, max uA uB}]
    {s : DynSystem S p} {t : DynSystem T q}
    {left : Boundary C (PFunctor.ulift.{uA, uB, max uS uB, max uS uA} p)}
    {right : Boundary C (PFunctor.ulift.{uA, uB, max uS uB, max uS uA} q)}
    {target : Boundary C (PFunctor.ulift.{uA, uB, max uS uB, max uS uA} r)}
    {lens : Lens (PFunctor.prod p q) r}
    (h₁ : IsRealizableBy C left (DynSystem.ulift s))
    (h₂ : IsRealizableBy C right (DynSystem.ulift t))
    (hlens : (Lens.comp
        lens.uliftMap.{uA, uB, uA, uB, max uS uB, max uS uA,
          max uS uB, max uS uA}
        (Lens.uliftProd p q)).IsChoiceAdmissible C left right target) :
    IsRealizableBy C target (DynSystem.ulift ((s.choiceProd t).wrap lens))

theorem IsRealizableBy.wrapChoiceProd
    {C : StepClass.{u, v}} [C.HasProd] [C.HasSum] [C.HasOption]
    [C.IsDistributive]
    {s : DynSystem S p} {t : DynSystem T q}
    {left : Boundary C p} {right : Boundary C q} {target : Boundary C r}
    {lens : Lens (PFunctor.prod p q) r}
    (h₁ : IsRealizableBy C left s) (h₂ : IsRealizableBy C right t)
    (hlens : lens.IsChoiceAdmissible C left right target) :
    IsRealizableBy C target ((s.choiceProd t).wrap lens)

theorem HasProd.map_mem [P : C.HasProd] {A B A' B' : Type u} {a : C.Str A}
    {b : C.Str B} {a' : C.Str A'} {b' : C.Str B'} {f : A → A'} {g : B → B'}
    (hf : C.Hom a a' f) (hg : C.Hom b b' g) :
    C.Hom (P.prod a b) (P.prod a' b') (Prod.map f g)

theorem HasProd.map_id_mem [P : C.HasProd] {A B : Type u} {a a' : C.Str A}
    {b b' : C.Str B} (ha : C.Hom a a' id) (hb : C.Hom b b' id) :
    C.Hom (P.prod a b) (P.prod a' b') id

theorem HasProd.pairRight_mem [P : C.HasProd] {A B D : Type u} {a : C.Str A}
    {b : C.Str B} {d : C.Str D} {f : A → B} (hf : C.Hom a b f) :
    C.Hom (P.prod a d) (P.prod b d) fun x => (f x.1, x.2)

theorem HasProd.pairLeft_mem [P : C.HasProd] {A B D : Type u} {a : C.Str A}
    {b : C.Str B} {d : C.Str D} {f : A → B} (hf : C.Hom a b f) :
    C.Hom (P.prod d a) (P.prod d b) fun x => (x.1, f x.2)

theorem HasProd.withInput_mem [P : C.HasProd] {A B : Type u} {a : C.Str A}
    {b : C.Str B} {f : A → B} (hf : C.Hom a b f) :
    C.Hom a (P.prod b a) fun x => (f x, x)

theorem HasSum.map_mem [S : C.HasSum] {A B A' B' : Type u} {a : C.Str A}
    {b : C.Str B} {a' : C.Str A'} {b' : C.Str B'} {f : A → A'} {g : B → B'}
    (hf : C.Hom a a' f) (hg : C.Hom b b' g) :
    C.Hom (S.sum a b) (S.sum a' b') (Sum.map f g)

theorem HasSum.map_id_mem [S : C.HasSum] {A B : Type u} {a a' : C.Str A}
    {b b' : C.Str B} (ha : C.Hom a a' id) (hb : C.Hom b b' id) :
    C.Hom (S.sum a b) (S.sum a' b') id

theorem HasOption.map_id_mem [C.HasProd] [O : C.HasOption] {A : Type u}
    {a a' : C.Str A} (ha : C.Hom a a' id) :
    C.Hom (O.option a) (O.option a') id

theorem IsDistributive.elimCtx_mem [P : C.HasProd] [S : C.HasSum]
    [D : C.IsDistributive] {A B E Z : Type u} {a : C.Str A} {b : C.Str B}
    {e : C.Str E} {z : C.Str Z} {f : A × E → Z} {g : B × E → Z}
    (hf : C.Hom (P.prod a e) z f) (hg : C.Hom (P.prod b e) z g) :
    C.Hom (P.prod (S.sum a b) e) z
      fun x => Sum.elim (fun l => f (l, x.2)) (fun r => g (r, x.2)) x.1

private theorem sumMap_fst_unpack {X : Type w}
    (step : (p + C.{uβ, uB} β).Obj X) :
    Sum.map id Sigma.fst (Resumption.unpack (β := β) step) = step.1.swap

theorem update?_of_view_query_of_ne [DecidableEq p.A]
    (M : DynComputation.{u} p α β) {state : M.State} {query : p.Obj M.State}
    (hview : M.view state = Sum.inr query) {index : p.Idx}
    (hne : index.1 ≠ query.1) : M.update? (state, index) = none

theorem updateFlat_of_view_query_of_ne [DecidableEq p.A]
    (M : DynComputation.{u} p α β) {state : M.State} {query : p.Obj M.State}
    (hview : M.view state = Sum.inr query) {index : p.Idx}
    (hne : index.1 ≠ query.1) : M.updateFlat (state, index) = state

@[simp] theorem stepD_of_view_return (M : DynComputation.{u} p α β)
    (handler : (a : p.A) → p.B a) {state : M.State} {value : β}
    (hview : M.view state = Sum.inl value) : M.stepD handler state = state

@[simp] theorem update?_setInit [DecidableEq p.A] {γ : Type uγ}
    (M : DynComputation.{u} p α β) (g : γ → M.State) (step : M.State × p.Idx) :
    (M.setInit g).update? step = M.update? step

@[simp] theorem updateFlat_setInit [DecidableEq p.A] {γ : Type uγ}
    (M : DynComputation.{u} p α β) (g : γ → M.State) (step : M.State × p.Idx) :
    (M.setInit g).updateFlat step = M.updateFlat step

@[simp] theorem expose_setInit [Inhabited p.A] {γ : Type uγ}
    (M : DynComputation.{u} p α β) (g : γ → M.State) (state : M.State) :
    (M.setInit g).expose state = M.expose state

@[simp] theorem update?_mapResult [DecidableEq p.A] {γ : Type uγ}
    (M : DynComputation.{u} p α β) (f : β → γ) (step : M.State × p.Idx) :
    (M.mapResult f).update? step = M.update? step

@[simp] theorem updateFlat_mapResult [DecidableEq p.A] {γ : Type uγ}
    (M : DynComputation.{u} p α β) (f : β → γ) (step : M.State × p.Idx) :
    (M.mapResult f).updateFlat step = M.updateFlat step

theorem seqComp_view_inl_of_query (M₁ : DynComputation.{u} p α β)
    (M₂ : DynComputation.{v} p β γ) {state₁ : M₁.State}
    {position : p.A} {next : p.B position → M₁.State}
    (hview : M₁.view state₁ = Sum.inr ⟨position, next⟩) :
    (M₁.seqComp M₂).view (Sum.inl state₁) =
      Sum.inr ⟨position, fun direction => Sum.inl (next direction)⟩

theorem isRealizableBy_pure {value : β}
    (hvalue : C.Hom bd.input bd.out fun _ : α => value) :
    IsRealizableBy C bd fun _ : α => (FreeM.pure value : FreeM p β)

theorem IsRealizableBy.precomp {γ : Type u} {inputRep : C.Str γ} {f : γ → α}
    (h : IsRealizableBy C bd program) (hf : C.Hom inputRep bd.input f) :
    IsRealizableBy C (bd.withInput inputRep) fun input => program (f input)

theorem cost_comp_le [Q.HasCategory] {A B D : Type u} {a : C.Str A} {b : C.Str B}
    {d : C.Str D} {f : A → B} {g : B → D}
    (rf : Q.Realizer a b f) (rg : Q.Realizer b d g) (input : A) :
    Q.cost (Q.compose rf rg) input ≤
      Q.cost rf input + Q.cost rg (f input) + Q.composeOverhead rf rg input

theorem cost_comp [Q.HasCategory] [Q.HasExactCategory]
    {A B D : Type u} {a : C.Str A} {b : C.Str B}
    {d : C.Str D} {f : A → B} {g : B → D}
    (rf : Q.Realizer a b f) (rg : Q.Realizer b d g) (input : A) :
    Q.cost (Q.compose rf rg) input =
      Q.cost rf input + Q.cost rg (f input) + Q.composeOverhead rf rg input

theorem add_le_add {actual₁ bound₁ actual₂ bound₂ : ExecutionCost}
    (h₁ : actual₁ ≤ bound₁) (h₂ : actual₂ ≤ bound₂) :
    actual₁ + actual₂ ≤ bound₁ + bound₂

theorem conforms_all {start finish : R.machine.State}
    (trace : ExecutionTrace R start finish) :
    trace.Conforms (fun _ _ ↦ True)

theorem Conforms.mono {allows allows' : ∀ position, p.B position → Prop}
    (hAllows : ∀ position direction, allows position direction → allows' position direction)
    {start finish : R.machine.State} {trace : ExecutionTrace R start finish}
    (h : trace.Conforms allows) : trace.Conforms allows'

theorem length_le_of_resolvesIn {start finish : R.machine.State} {budget : ℕ}
    (trace : ExecutionTrace R start finish) (resolves : R.machine.ResolvesIn budget start) :
    trace.length ≤ budget

theorem update_eq_some {state : R.machine.State} {position : p.A}
    {next : p.B position → R.machine.State}
    (view_eq : R.machine.view state = Sum.inr ⟨position, next⟩)
    (direction : p.B position) :
    R.machine.update? (state, ⟨position, direction⟩) = some (next direction)

theorem conforms_append {allows : ∀ position, p.B position → Prop}
    {start middle finish : R.machine.State}
    (left : ExecutionTrace R start middle) (right : ExecutionTrace R middle finish) :
    (left.append right).Conforms allows ↔ left.Conforms allows ∧ right.Conforms allows

theorem cost_append {start middle finish : R.machine.State}
    (left : ExecutionTrace R start middle) (right : ExecutionTrace R middle finish) :
    cost (left.append right) = cost left + cost right

theorem ResolvesInUnder.mono {M : DynComputation.{u} p α β}
    {allows : ∀ position, p.B position → Prop} {j k : ℕ} {state : M.State}
    (h : M.ResolvesInUnder allows j state) (hjk : j ≤ k) :
    M.ResolvesInUnder allows k state

theorem ResolvesInUnder.antitone {M : DynComputation.{u} p α β}
