  onPos

@[simp] theorem length_prependLeft {state : R₁.machine.State} {position : p.A}
    {next : p.B position → R₁.machine.State}
    (view_eq : R₁.machine.view state = Sum.inr ⟨position, next⟩)
    (direction : p.B position)
    {finish : R₁.machine.State ⊕ R₂.machine.State}
    (source : SeqCompTraceSource R₁ R₂ (next direction) finish) :
    (source.prependLeft view_eq direction).length = source.length + 1

@[simp] theorem conforms_prependLeft (allows : ∀ position, p.B position → Prop)
    {state : R₁.machine.State} {position : p.A}
    {next : p.B position → R₁.machine.State}
    (view_eq : R₁.machine.view state = Sum.inr ⟨position, next⟩)
    (direction : p.B position)
    {finish : R₁.machine.State ⊕ R₂.machine.State}
    (source : SeqCompTraceSource R₁ R₂ (next direction) finish) :
    (source.prependLeft view_eq direction).Conforms allows ↔
      allows position direction ∧ source.Conforms allows

theorem length_seqCompSource (R₁ : QuantitativeRealization Q bd)
    (R₂ : QuantitativeRealization Q (bd.mid outRep)) {start : R₁.machine.State}
    {finish : R₁.machine.State ⊕ R₂.machine.State}
    (trace : (R₁.seqComp R₂).ExecutionTrace (Sum.inl start) finish) :
    (trace.seqCompSource R₁ R₂).length = trace.length

theorem SeqCompTraceSource.response_exists
    {R₁ : QuantitativeRealization Q bd}
    {R₂ : QuantitativeRealization Q (bd.mid outRep)}
    {allows : ∀ position, p.B position → Prop}
    {firstBound : A → ExecutionCost} {secondBound : B → ExecutionCost}
    (first : R₁.RunsWithinUnder allows firstBound)
    (second : R₂.RunsWithinUnder allows secondBound)
    (input : A) {finish : R₁.machine.State ⊕ R₂.machine.State}
    (source : SeqCompTraceSource R₁ R₂ (R₁.machine.init input) finish)
    (hsource : source.Conforms allows) {position : p.A}
    {next : p.B position → R₁.machine.State ⊕ R₂.machine.State}
    (view_eq : (R₁.seqComp R₂).machine.view finish = Sum.inr ⟨position, next⟩) :
    ∃ direction, allows position direction

theorem QuantitativeRealization.traceProgressUnder_seqComp
    {R₁ : QuantitativeRealization Q bd}
    {R₂ : QuantitativeRealization Q (bd.mid outRep)}
    {allows : ∀ position, p.B position → Prop}
    {firstBound : A → ExecutionCost} {secondBound : B → ExecutionCost}
    (first : R₁.RunsWithinUnder allows firstBound)
    (second : R₂.RunsWithinUnder allows secondBound) (input : A) :
    (R₁.seqComp R₂).TraceProgressUnder allows input

theorem SeqCompTraceSource.cost_le
    {R₁ : QuantitativeRealization Q bd}
    {R₂ : QuantitativeRealization Q (bd.mid outRep)}
    {allows : ∀ position, p.B position → Prop}
    {firstBound : A → ExecutionCost} {secondBound : B → ExecutionCost}
    (first : R₁.RunsWithinUnder allows firstBound)
    (second : R₂.RunsWithinUnder allows secondBound)
    (handoff : SeqCompHandoffBound R₁ allows secondBound) (input : A)
    {finish : R₁.machine.State ⊕ R₂.machine.State}
    (source : SeqCompTraceSource R₁ R₂ (R₁.machine.init input) finish)
    (hsource : source.Conforms allows) :
    source.cost input ≤ firstBound input + handoff.bound input

theorem SeqCompTraceSource.length_le
    {R₁ : QuantitativeRealization Q bd}
    {R₂ : QuantitativeRealization Q (bd.mid outRep)}
    {allows : ∀ position, p.B position → Prop}
    {firstBound : A → ExecutionCost} {secondBound : B → ExecutionCost}
    (first : R₁.RunsWithinUnder allows firstBound)
    (second : R₂.RunsWithinUnder allows secondBound)
    (handoff : SeqCompHandoffBound R₁ allows secondBound) (input : A)
    {finish : R₁.machine.State ⊕ R₂.machine.State}
    (source : SeqCompTraceSource R₁ R₂ (R₁.machine.init input) finish)
    (hsource : source.Conforms allows) :
    source.length ≤ (firstBound input + handoff.bound input).queries

theorem QuantitativeRealization.resolvesInUnder_seqComp
    {R₁ : QuantitativeRealization Q bd}
    {R₂ : QuantitativeRealization Q (bd.mid outRep)}
    {allows : ∀ position, p.B position → Prop}
    {firstBound : A → ExecutionCost} {secondBound : B → ExecutionCost}
    (first : R₁.RunsWithinUnder allows firstBound)
    (second : R₂.RunsWithinUnder allows secondBound)
    (handoff : SeqCompHandoffBound R₁ allows secondBound) (input : A) :
    (R₁.seqComp R₂).machine.ResolvesInUnder allows
      (firstBound input + handoff.bound input).queries
      ((R₁.seqComp R₂).machine.init input)

theorem QuantitativeRealization.RunsWithinUnder.seqComp
    {R₁ : QuantitativeRealization Q bd}
    {R₂ : QuantitativeRealization Q (bd.mid outRep)}
    {allows : ∀ position, p.B position → Prop}
    {firstBound : A → ExecutionCost} {secondBound : B → ExecutionCost}
    (first : R₁.RunsWithinUnder allows firstBound)
    (second : R₂.RunsWithinUnder allows secondBound)
    (handoff : SeqCompHandoffBound R₁ allows secondBound)
    (certificate : SeqCompCostCertificate R₁ R₂ allows) :
    (R₁.seqComp R₂).RunsWithinUnder allows fun input ↦
      firstBound input + handoff.bound input + certificate.overhead input

private theorem simulate_eq_iter {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (h : Handler E F) (t : ITree E α) :
    simulate h t = iter (simulateStep h) t

private theorem simulateStep_pure {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (h : Handler E F) (r : α) :
    simulateStep h (pure (F := E) r) = (pure (.inr r) : ITree F (ITree E α ⊕ α))

theorem simulate_pure {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uFB}}
    {α : Type uα} (h : Handler E F) (r : α) :
    simulate h (pure (F := E) r) = pure r

private theorem simulateStep_step {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (h : Handler E F) (t : ITree E α) :
    simulateStep h (step t) = (pure (.inl t) : ITree F (ITree E α ⊕ α))

private theorem simulateStep_query {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (h : Handler E F) (a : E.A)
    (k : E.B a → ITree E α) :
    simulateStep h (query a k) =
      (bind (h a) (fun b => pure (.inl (k b))) : ITree F (ITree E α ⊕ α))

theorem simulate_step_eq {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uFB}}
    {α : Type uα} (h : Handler E F) (t : ITree E α) :
    simulate h (step t) = step (simulate h t)

theorem simulate_step {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uFB}}
    {α : Type uα} (h : Handler E F) (t : ITree E α) :
    WeakBisim (simulate h (step t)) (simulate h t)

theorem simulate_query_eq_bind {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (h : Handler E F) (a : E.A) (k : E.B a → ITree E α) :
    simulate h (query a k) = bind (h a) (fun b => step (simulate h (k b)))

theorem TauSteps.simulate {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα} {t t' : ITree E α}
    (ht : TauSteps t t') (h : Handler E F) :
    TauSteps (ITree.simulate h t) (ITree.simulate h t')

theorem simulate_weakBisimRel {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα} {β : Type uβ}
    {RR : α → β → Prop} (h : Handler E F) {t : ITree E α} {s : ITree E β}
    (hts : WeakBisimRel RR t s) :
    WeakBisimRel RR (simulate h t) (simulate h s)

theorem simulate_id {E : PFunctor.{uEA, uEB}} {α : Type uα}
    (t : ITree E α) :
    WeakBisim (simulate (Handler.id E) t) t

theorem Handler.id_comp_apply {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} (h : Handler E F) (a : E.A) :
    WeakBisim ((Handler.id F).comp h a) (h a)

theorem Handler.comp_id_apply {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} (h : Handler E F) (a : E.A) :
    WeakBisim (h.comp (Handler.id E) a) (h a)

theorem simulate_bind {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uFB}}
    {α : Type uα} {β : Type uβ}
    (h : Handler E F) (t : ITree E α) (k : α → ITree E β) :
    WeakBisim (simulate h (bind t k))
      (bind (simulate h t) (fun a => simulate h (k a)))

theorem simulate_comp {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uFB}}
    {G : PFunctor.{uGA, uGB}} {α : Type uα}
    (outer : Handler F G) (inner : Handler E F) (t : ITree E α) :
    WeakBisim (simulate outer (simulate inner t))
      (simulate (outer.comp inner) t)

theorem Handler.comp_assoc_apply {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {G : PFunctor.{uGA, uGB}}
    {H : PFunctor.{uHA, uHB}}
    (third : Handler G H) (second : Handler F G) (first : Handler E F)
    (a : E.A) :
    WeakBisim (third.comp (second.comp first) a)
      ((third.comp second).comp first a)

@[simp] theorem mapSpec_pure {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (r : α) :
    mapSpec φ (pure (F := E) r) = pure r

@[simp] theorem mapSpec_step {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (t : ITree E α) :
    mapSpec φ (step t) = step (mapSpec φ t)

@[simp] theorem mapSpec_query {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (a : E.A) (k : E.B a → ITree E α) :
    mapSpec φ (query a k) =
      query (φ.toFunA a) (fun b => mapSpec φ (k (φ.toFunB a b)))

theorem mapSpec_id {E : PFunctor.{uEA, uEB}} {α : Type uα}
    (t : ITree E α) :
    mapSpec (PFunctor.Lens.id E) t = t

theorem dest_mapSpec {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (u : ITree E α) :
    ITree.shape' (mapSpec φ u) =
      ⟨(mapSpecStep φ u).1, fun b => mapSpec φ ((mapSpecStep φ u).2 b)⟩

theorem shape'_mapSpec {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (u : ITree E α) :
    shape' (mapSpec φ u) =
      ⟨(mapSpecStep φ u).1, fun b => mapSpec φ ((mapSpecStep φ u).2 b)⟩

theorem mapSpec_comp {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uFB}}
    {G : PFunctor.{uGA, uGB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (ψ : PFunctor.Lens F G) (t : ITree E α) :
    mapSpec (ψ ∘ₗ φ) t = mapSpec ψ (mapSpec φ t)

theorem mapSpec_bind {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα} {β : Type uβ}
    (φ : PFunctor.Lens E F)
    (t : ITree E α) (k : α → ITree E β) :
    mapSpec φ (bind t k) = bind (mapSpec φ t) (fun a => mapSpec φ (k a))

theorem mapSpec_iter {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα} {β : Type uβ}
    (φ : PFunctor.Lens E F)
    (body : β → ITree E (β ⊕ α)) (init : β) :
    mapSpec φ (iter body init) = iter (fun j => mapSpec φ (body j)) init

@[simp] theorem mapSpec_map {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα} {β : Type uβ}
    (φ : PFunctor.Lens E F) (f : α → β) (t : ITree E α) :
    mapSpec φ (ITree.map f t) = ITree.map f (mapSpec φ t)

theorem mapSpec_functorMap {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α β : Type u}
    (φ : PFunctor.Lens E F) (f : α → β)
    (t : ITree E α) : mapSpec φ (f <$> t) = f <$> mapSpec φ t

@[simp] theorem mapSpec_cat {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα} {β : Type uβ}
    {γ : Type uγ} (φ : PFunctor.Lens E F)
    (f : α → ITree E β) (g : β → ITree E γ) (a : α) :
    mapSpec φ (ITree.cat f g a) =
      ITree.cat (mapSpec φ ∘ f) (mapSpec φ ∘ g) a

@[simp] theorem mapSpec_seq {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α β : Type u}
    (φ : PFunctor.Lens E F) (mf : ITree E (α → β))
    (mx : ITree E α) :
    mapSpec φ (mf <*> mx) = mapSpec φ mf <*> mapSpec φ mx

theorem simulate_ofLens {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {α : Type uα}
    (φ : PFunctor.Lens E F) (t : ITree E α) :
    WeakBisim (simulate (Handler.ofLens φ) t) (mapSpec φ t)

theorem Handler.ofLens_comp_apply {E : PFunctor.{uEA, uEB}}
    {F : PFunctor.{uFA, uFB}} {G : PFunctor.{uGA, uGB}}
    (φ : PFunctor.Lens E F)
    (ψ : PFunctor.Lens F G) (a : E.A) :
    WeakBisim ((Handler.ofLens ψ).comp (Handler.ofLens φ) a)
      (Handler.ofLens (ψ ∘ₗ φ) a)

theorem comp_case {E : PFunctor.{uEA, uEB}} {F : PFunctor.{uFA, uEB}}
    {G : PFunctor.{uGA, uGB}} {H : PFunctor.{uHA, uHB}}
    (outer : Handler G H) (left : Handler E G) (right : Handler F G) :
    outer.comp (Handler.case_ left right) =
