theorem transport_trans
    {Q : PFunctor.{uA', uB'}}
    {S : Display.{uA, uB, uC, uD} P}
    {T : Display.{uA', uB', uC', uD'} Q}
    {f g h : PFunctor.Handler (FreeM Q) P} (hfg : f = g) (hgh : g = h)
