theorem parallelSumAssoc_natural_total
    {P : PFunctor.{uA₁, uB}} {Q : PFunctor.{uA₂, uB}}
    {R : PFunctor.{uA₃, uB}}
    {P' : PFunctor.{uA₄, uB}} {Q' : PFunctor.{uA₅, uB}}
    {R' : PFunctor.{uA₆, uB}}
    {S₁ : Display.{uA₁, uB, uC₁, uD₁} P}
    {T₁ : Display.{uA₂, uB, uC₂, uD₂} Q}
    {U₁ : Display.{uA₃, uB, uC₃, uD₃} R}
    {S₂ : Display.{uA₄, uB, uC₄, uD₄} P'}
    {T₂ : Display.{uA₅, uB, uC₅, uD₅} Q'}
    {U₂ : Display.{uA₆, uB, uC₆, uD₆} R'}
    {leftBase : PFunctor.Lens P P'}
    {middleBase : PFunctor.Lens Q Q'}
    {rightBase : PFunctor.Lens R R'}
    (left : Display.Lens S₁ S₂ leftBase)
    (middle : Display.Lens T₁ T₂ middleBase)
    (right : Display.Lens U₁ U₂ rightBase) :
    TotalEq
      (comp (parallelSumAssoc S₂ T₂ U₂)
        (parallelSumMap (parallelSumMap left middle) right))
      (comp (parallelSumMap left (parallelSumMap middle right))
        (parallelSumAssoc S₁ T₁ U₁))

theorem parallelSumAssoc_natural
    {P : PFunctor.{uA₁, uB}} {Q : PFunctor.{uA₂, uB}}
    {R : PFunctor.{uA₃, uB}}
    {P' : PFunctor.{uA₄, uB}} {Q' : PFunctor.{uA₅, uB}}
    {R' : PFunctor.{uA₆, uB}}
    {S₁ : Display.{uA₁, uB, uC₁, uD₁} P}
    {T₁ : Display.{uA₂, uB, uC₂, uD₂} Q}
    {U₁ : Display.{uA₃, uB, uC₃, uD₃} R}
    {S₂ : Display.{uA₄, uB, uC₄, uD₄} P'}
    {T₂ : Display.{uA₅, uB, uC₅, uD₅} Q'}
    {U₂ : Display.{uA₆, uB, uC₆, uD₆} R'}
    {leftBase : PFunctor.Lens P P'}
    {middleBase : PFunctor.Lens Q Q'}
    {rightBase : PFunctor.Lens R R'}
    (left : Display.Lens S₁ S₂ leftBase)
    (middle : Display.Lens T₁ T₂ middleBase)
    (right : Display.Lens U₁ U₂ rightBase) :
    transport
        (PFunctor.Lens.parallelSumAssoc_natural
          leftBase middleBase rightBase)
        (comp (parallelSumAssoc S₂ T₂ U₂)
          (parallelSumMap (parallelSumMap left middle) right)) =
      comp (parallelSumMap left (parallelSumMap middle right))
        (parallelSumAssoc S₁ T₁ U₁)

@[simp] theorem parallel_left
    {P : PFunctor.{uA₁, uB}} {Q : PFunctor.{uA₂, uB}} {R : PFunctor.{uA₃, uB}}
    {V : PFunctor.{uA₄, uB}} {S : Display.{uA₁, uB, uC₁, uD₁} P} {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {U : Display.{uA₃, uB, uC₃, uD₃} R} {W : Display.{uA₄, uB, uC₄, uD₄} V}
    {leftHandler : PFunctor.Handler (FreeM R) P} {rightHandler : PFunctor.Handler (FreeM V) Q}
    (displayedLeft : Display.Handler S U leftHandler)
    (displayedRight : Display.Handler T W rightHandler)
    (a : P.A) (contract : S.position a) :
    parallel displayedLeft displayedRight (.left a) (ULift.up contract) =
      FreeM.Displayed.leftMap (T := W) (fun _ => ULift.up) (leftHandler a)
        (displayedLeft a contract)

@[simp] theorem parallel_right
    {P : PFunctor.{uA₁, uB}} {Q : PFunctor.{uA₂, uB}} {R : PFunctor.{uA₃, uB}}
    {V : PFunctor.{uA₄, uB}} {S : Display.{uA₁, uB, uC₁, uD₁} P} {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {U : Display.{uA₃, uB, uC₃, uD₃} R} {W : Display.{uA₄, uB, uC₄, uD₄} V}
    {leftHandler : PFunctor.Handler (FreeM R) P} {rightHandler : PFunctor.Handler (FreeM V) Q}
    (displayedLeft : Display.Handler S U leftHandler)
    (displayedRight : Display.Handler T W rightHandler)
    (b : Q.A) (contract : T.position b) :
    parallel displayedLeft displayedRight (.right b) (ULift.up contract) =
      FreeM.Displayed.rightMap (S := U) (fun _ => ULift.up) (rightHandler b)
        (displayedRight b contract)

@[simp] theorem parallel_both
    {P : PFunctor.{uA₁, uB}} {Q : PFunctor.{uA₂, uB}} {R : PFunctor.{uA₃, uB}}
    {V : PFunctor.{uA₄, uB}} {S : Display.{uA₁, uB, uC₁, uD₁} P} {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {U : Display.{uA₃, uB, uC₃, uD₃} R} {W : Display.{uA₄, uB, uC₄, uD₄} V}
    {leftHandler : PFunctor.Handler (FreeM R) P} {rightHandler : PFunctor.Handler (FreeM V) Q}
    (displayedLeft : Display.Handler S U leftHandler)
    (displayedRight : Display.Handler T W rightHandler)
    (a : P.A) (b : Q.A)
    (leftContract : S.position a) (rightContract : T.position b) :
    parallel displayedLeft displayedRight (.both a b)
        (leftContract, rightContract) =
      FreeM.Displayed.parallel (leftHandler a) (rightHandler b)
        (displayedLeft a leftContract) (displayedRight b rightContract)

