@[simp] theorem comp_toState
    {MiddleState : Type uC₂} {middle : Responder MiddleState RPoly}
    {MiddleWitness : MiddleState → Type uD₂}
    {displayedMiddle : Display.Coalgebra (Display.responder S)
      middle.out MiddleWitness}
    {FinalState : Type uC₄} {final : Responder FinalState RPoly}
    {FinalWitness : FinalState → Type uD₄}
    {displayedFinal : Display.Coalgebra (Display.responder S)
      final.out FinalWitness}
    (second : PresentationHom S middle MiddleWitness
      displayedMiddle final FinalWitness displayedFinal)
    (first : PresentationHom S source SourceWitness displayedSource
      middle MiddleWitness displayedMiddle) (state : SourceState) :
    (second.comp first).toState state =
      second.toState (first.toState state)

@[simp] theorem comp_toWitness
    {MiddleState : Type uC₂} {middle : Responder MiddleState RPoly}
    {MiddleWitness : MiddleState → Type uD₂}
    {displayedMiddle : Display.Coalgebra (Display.responder S)
      middle.out MiddleWitness}
    {FinalState : Type uC₄} {final : Responder FinalState RPoly}
    {FinalWitness : FinalState → Type uD₄}
    {displayedFinal : Display.Coalgebra (Display.responder S)
      final.out FinalWitness}
    (second : PresentationHom S middle MiddleWitness
      displayedMiddle final FinalWitness displayedFinal)
    (first : PresentationHom S source SourceWitness displayedSource
      middle MiddleWitness displayedMiddle)
    (state : SourceState) (witness : SourceWitness state) :
    (second.comp first).toWitness state witness =
      second.toWitness (first.toState state)
        (first.toWitness state witness)

theorem comp_assoc
    {MiddleState : Type uC₂} {middle : Responder MiddleState RPoly}
    {MiddleWitness : MiddleState → Type uD₂}
    {displayedMiddle : Display.Coalgebra (Display.responder S)
      middle.out MiddleWitness}
    {NextState : Type uC₄} {next : Responder NextState RPoly}
    {NextWitness : NextState → Type uD₄}
    {displayedNext : Display.Coalgebra (Display.responder S)
      next.out NextWitness}
    {FinalState : Type uC₅} {final : Responder FinalState RPoly}
    {FinalWitness : FinalState → Type uD₅}
    {displayedFinal : Display.Coalgebra (Display.responder S)
      final.out FinalWitness}
    (third : PresentationHom S next NextWitness displayedNext
      final FinalWitness displayedFinal)
    (second : PresentationHom S middle MiddleWitness
      displayedMiddle next NextWitness displayedNext)
    (first : PresentationHom S source SourceWitness displayedSource
      middle MiddleWitness displayedMiddle) :
    (third.comp second).comp first = third.comp (second.comp first)

theorem mapDisplayedBehavior_transport
    {R : PFunctor.{uA₂, uB₂}}
    {S : Display.{uA₁, uB₁, uC₁, uD₁} P}
    {T : Display.{uA₂, uB₂, uC₂, uD₂} R}
    {f : PFunctor.Lens P R} (df : Display.Lens S T f)
    {first second : PFunctor.M (R ⊸ y.{uA₂, uB₂})}
    (h : first = second) (displayed : Display.M (Display.responder T) first) :
    Display.M.transport (congrArg (mapBehavior f) h)
        (mapDisplayedBehavior df first displayed) =
      mapDisplayedBehavior df second (Display.M.transport h displayed)

theorem mapDisplayedBehavior_comp
    {P : PFunctor.{uA₁, uB₁}} {Q : PFunctor.{uA₂, uB₁}}
    {R : PFunctor.{uA₃, uB₃}}
    {S : Display.{uA₁, uB₁, uC₁, uD₁} P}
    {T : Display.{uA₂, uB₁, uC₂, uD₂} Q}
    {U : Display.{uA₃, uB₃, uC₃, uD₃} R}
    {firstBase : PFunctor.Lens P Q}
    {secondBase : PFunctor.Lens Q R}
    (first : Display.Lens S T firstBase)
    (second : Display.Lens T U secondBase)
    (behavior : PFunctor.M (R ⊸ y.{uA₃, uB₃}))
    (displayedBehavior : Display.M (Display.responder U) behavior) :
    Display.M.transport (mapBehavior_comp firstBase secondBase behavior)
        (mapDisplayedBehavior first (mapBehavior secondBase behavior)
          (mapDisplayedBehavior second behavior displayedBehavior)) =
      mapDisplayedBehavior (Display.Lens.comp second first)
        behavior displayedBehavior

theorem runFree_eq_liftM
    {Q : PFunctor.{uA', uB}} {State : Type uB}
    (R : Responder State Q) {E : Type uB}
    (program : FreeM Q E) (state : State) :
    R.runFree program state = program.liftM R.toStateHandler state

theorem runFree_eq_statefulRun
    {Q : PFunctor.{uA', uB}} {State : Type uB}
    (R : Responder State Q) {E : Type uB}
    (program : FreeM Q E) (state : State) :
    R.runFree program state = R.toStateHandler.run program state

