@[simp] theorem parallel_toState
    {S : Display.{uA₁, uB, uC₁, uD₁} P}
    {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {SourceState₁ : Type uS₁} {SourceState₂ : Type uS₂}
    {TargetState₁ : Type uT₁} {TargetState₂ : Type uT₂}
    {source₁ : Responder SourceState₁ P} {source₂ : Responder SourceState₂ Q}
    {target₁ : Responder TargetState₁ P} {target₂ : Responder TargetState₂ Q}
    {SourceWitness₁ : SourceState₁ → Type uI₁}
    {SourceWitness₂ : SourceState₂ → Type uI₂}
    {TargetWitness₁ : TargetState₁ → Type uJ₁}
    {TargetWitness₂ : TargetState₂ → Type uJ₂}
    {dS₁ : Display.Coalgebra (Display.responder S) source₁.out SourceWitness₁}
    {dS₂ : Display.Coalgebra (Display.responder T) source₂.out SourceWitness₂}
    {dT₁ : Display.Coalgebra (Display.responder S) target₁.out TargetWitness₁}
    {dT₂ : Display.Coalgebra (Display.responder T) target₂.out TargetWitness₂}
    (f : PresentationHom S source₁ SourceWitness₁ dS₁ target₁ TargetWitness₁ dT₁)
    (g : PresentationHom T source₂ SourceWitness₂ dS₂ target₂ TargetWitness₂ dT₂)
    (state : SourceState₁ × SourceState₂) :
    (f.parallel g).toState state = (f.toState state.1, g.toState state.2)

@[simp] theorem parallel_toWitness
    {S : Display.{uA₁, uB, uC₁, uD₁} P}
    {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {SourceState₁ : Type uS₁} {SourceState₂ : Type uS₂}
    {TargetState₁ : Type uT₁} {TargetState₂ : Type uT₂}
    {source₁ : Responder SourceState₁ P} {source₂ : Responder SourceState₂ Q}
    {target₁ : Responder TargetState₁ P} {target₂ : Responder TargetState₂ Q}
    {SourceWitness₁ : SourceState₁ → Type uI₁}
    {SourceWitness₂ : SourceState₂ → Type uI₂}
    {TargetWitness₁ : TargetState₁ → Type uJ₁}
    {TargetWitness₂ : TargetState₂ → Type uJ₂}
    {dS₁ : Display.Coalgebra (Display.responder S) source₁.out SourceWitness₁}
    {dS₂ : Display.Coalgebra (Display.responder T) source₂.out SourceWitness₂}
    {dT₁ : Display.Coalgebra (Display.responder S) target₁.out TargetWitness₁}
    {dT₂ : Display.Coalgebra (Display.responder T) target₂.out TargetWitness₂}
    (f : PresentationHom S source₁ SourceWitness₁ dS₁ target₁ TargetWitness₁ dT₁)
    (g : PresentationHom T source₂ SourceWitness₂ dS₂ target₂ TargetWitness₂ dT₂)
    (state : SourceState₁ × SourceState₂)
    (witness : SourceWitness₁ state.1 × SourceWitness₂ state.2) :
    (f.parallel g).toWitness state witness =
      (f.toWitness state.1 witness.1, g.toWitness state.2 witness.2)

@[simp] theorem parallel_id
    {S : Display.{uA₁, uB, uC₁, uD₁} P}
    {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {State₁ : Type uS₁} {State₂ : Type uS₂}
    {source₁ : Responder State₁ P} {source₂ : Responder State₂ Q}
    {Witness₁ : State₁ → Type uI₁}
    {Witness₂ : State₂ → Type uI₂}
    {displayed₁ : Display.Coalgebra (Display.responder S)
      source₁.out Witness₁}
    {displayed₂ : Display.Coalgebra (Display.responder T)
      source₂.out Witness₂} :
    (PresentationHom.id (S := S) (source := source₁)
      (SourceWitness := Witness₁) (displayedSource := displayed₁)).parallel
      (PresentationHom.id (S := T) (source := source₂)
        (SourceWitness := Witness₂) (displayedSource := displayed₂)) =
      PresentationHom.id

theorem parallel_comp
    {S : Display.{uA₁, uB, uC₁, uD₁} P}
    {T : Display.{uA₂, uB, uC₂, uD₂} Q}
    {SourceState₁ : Type uS₁} {SourceState₂ : Type uS₂}
    {MiddleState₁ : Type uT₁} {MiddleState₂ : Type uT₂}
    {FinalState₁ : Type uK₁} {FinalState₂ : Type uK₂}
    {source₁ : Responder SourceState₁ P}
    {source₂ : Responder SourceState₂ Q}
    {middle₁ : Responder MiddleState₁ P}
    {middle₂ : Responder MiddleState₂ Q}
    {final₁ : Responder FinalState₁ P}
    {final₂ : Responder FinalState₂ Q}
    {SourceWitness₁ : SourceState₁ → Type uI₁}
    {SourceWitness₂ : SourceState₂ → Type uI₂}
    {MiddleWitness₁ : MiddleState₁ → Type uJ₁}
    {MiddleWitness₂ : MiddleState₂ → Type uJ₂}
    {FinalWitness₁ : FinalState₁ → Type uL₁}
    {FinalWitness₂ : FinalState₂ → Type uL₂}
    {displayedSource₁ : Display.Coalgebra (Display.responder S)
      source₁.out SourceWitness₁}
    {displayedSource₂ : Display.Coalgebra (Display.responder T)
      source₂.out SourceWitness₂}
    {displayedMiddle₁ : Display.Coalgebra (Display.responder S)
      middle₁.out MiddleWitness₁}
    {displayedMiddle₂ : Display.Coalgebra (Display.responder T)
      middle₂.out MiddleWitness₂}
    {displayedFinal₁ : Display.Coalgebra (Display.responder S)
      final₁.out FinalWitness₁}
    {displayedFinal₂ : Display.Coalgebra (Display.responder T)
      final₂.out FinalWitness₂}
    (first₁ : PresentationHom S source₁ SourceWitness₁
      displayedSource₁ middle₁ MiddleWitness₁ displayedMiddle₁)
    (first₂ : PresentationHom T source₂ SourceWitness₂
      displayedSource₂ middle₂ MiddleWitness₂ displayedMiddle₂)
    (second₁ : PresentationHom S middle₁ MiddleWitness₁
      displayedMiddle₁ final₁ FinalWitness₁ displayedFinal₁)
    (second₂ : PresentationHom T middle₂ MiddleWitness₂
      displayedMiddle₂ final₂ FinalWitness₂ displayedFinal₂) :
    (second₁.parallel second₂).comp (first₁.parallel first₂) =
      (second₁.comp first₁).parallel (second₂.comp first₂)

@[simp]
theorem split_join {program : FreeM P α}
    {suffix : Path program → FreeM P β}
    (view : AppendView program suffix) :
    split program suffix view.join = view

@[simp] theorem ofCompletion_occurrence {target : P.A} {program : FreeM P α} {n : Nat}
    {occ : Occurrence target program n} (completion : occ.Completion) :
    (ofCompletion completion).occurrence = occ

@[simp] theorem ofCompletion_completion {target : P.A} {program : FreeM P α} {n : Nat}
    {occ : Occurrence target program n} (completion : occ.Completion) :
    (ofCompletion completion).completion = completion

theorem fork_eq_map_complete {target : P.A}
    {program : FreeM P α} {path : Path program} {n : Nat}
    (located : Located target program path n) :
    located.fork =
      FreeM.map (fun second : located.occurrence.Completion => ({
        occurrence := located.occurrence
        first := located.completion
        second := second } : ForkView target program n))
        located.occurrence.complete

theorem fork_prependSame {target : P.A}
    {next : P.B target → FreeM P α} (answer : P.B target)
    {suffix : Path (next answer)} {n : Nat}
    (located : Located target (next answer) suffix n) :
    (prependSame answer located).fork =
      FreeM.map (ForkView.prependSame answer) located.fork

theorem fork_prependOther {target a : P.A}
    {next : P.B a → FreeM P α} (hne : a ≠ target) (answer : P.B a)
    {suffix : Path (next answer)} {n : Nat}
    (located : Located target (next answer) suffix n) :
    (prependOther hne answer located).fork =
      FreeM.map (ForkView.prependOther hne answer) located.fork

@[simp] theorem forLabel_mk_of_ne [DecidableEq κ] {label other : κ}
    (hne : other ≠ label) (view : ForkView target program (index other)) :
    forLabel label (⟨other, view⟩ : SelectedForkView target program κ index) = none

theorem valid_prependSame {next : P.B target → FreeM P α}
    (answer : P.B target) {n : Nat} (result : Split target (next answer) n)
    (hresult : result.Valid) : (prependSame answer result).Valid

theorem valid_prependOther {a : P.A} {next : P.B a → FreeM P α}
    (hne : a ≠ target) (answer : P.B a) {n : Nat}
    (result : Split target (next answer) n) (hresult : result.Valid) :
    (prependOther hne answer result).Valid

theorem complete_prependOther {a : P.A} {next : P.B a → FreeM P α}
    (hne : a ≠ target) (answer : P.B a) {n : Nat}
    (result : Split target (next answer) n) :
    complete (prependOther hne answer result) =
      FreeM.map (fun path => (⟨answer, path⟩ : Path (FreeM.liftBind a next)))
        (complete result)

theorem length_le_of_isTotalRollBound (program : FreeM P α) {bound : Nat}
    (hbound : program.IsTotalRollBound bound) (path : Path program) :
    length program path ≤ bound

@[simp, freeM_unfold]
theorem stateChain_zero {Γ : P.A → Type w₂}
    {a : α} {Stage : Nat → Type w}
    {s : (i : Nat) → Stage i → FreeM P α}
    {advance : (i : Nat) → (state : Stage i) → Path (s i state) → Stage (i + 1)}
    (deco : (i : Nat) → (state : Stage i) → Decoration Γ (s i state))
    (i : Nat) (state : Stage i) :
    Decoration.stateChain (a := a) (advance := advance) deco 0 i state =
      (⟨⟩ : Decoration Γ (FreeM.stateChain a Stage s advance 0 i state))

@[simp, freeM_unfold]
theorem stateChain_succ {Γ : P.A → Type w₂}
    {a : α} {Stage : Nat → Type w}
    {s : (i : Nat) → Stage i → FreeM P α}
    {advance : (i : Nat) → (state : Stage i) → Path (s i state) → Stage (i + 1)}
    (deco : (i : Nat) → (state : Stage i) → Decoration Γ (s i state))
    (n : Nat) (i : Nat) (state : Stage i) :
    Decoration.stateChain (a := a) (advance := advance) deco (n + 1) i state =
      Decoration.append (deco i state)
        (fun path =>
          Decoration.stateChain (a := a) deco n (i + 1) (advance i state path))

@[simp, freeM_unfold]
theorem stateChain_zero {Γ : P.A → Type w₂} {F : (a : P.A) → Γ a → Type w₃}
    {a : α} {Stage : Nat → Type w}
    {s : (i : Nat) → Stage i → FreeM P α}
    {advance : (i : Nat) → (state : Stage i) → Path (s i state) → Stage (i + 1)}
    {deco : (i : Nat) → (state : Stage i) → Decoration Γ (s i state)}
    (rDeco : (i : Nat) → (state : Stage i) →
      Decoration.Over Γ F (s i state) (deco i state))
    (i : Nat) (state : Stage i) :
    Decoration.Over.stateChain (a := a) (advance := advance) rDeco 0 i state =
      (⟨⟩ : Decoration.Over Γ F
        (FreeM.stateChain a Stage s advance 0 i state)
        (Decoration.stateChain deco 0 i state))

@[simp, freeM_unfold]
theorem stateChain_succ {Γ : P.A → Type w₂} {F : (a : P.A) → Γ a → Type w₃}
    {a : α} {Stage : Nat → Type w}
    {s : (i : Nat) → Stage i → FreeM P α}
    {advance : (i : Nat) → (state : Stage i) → Path (s i state) → Stage (i + 1)}
    {deco : (i : Nat) → (state : Stage i) → Decoration Γ (s i state)}
    (rDeco : (i : Nat) → (state : Stage i) →
      Decoration.Over Γ F (s i state) (deco i state))
    (n : Nat) (i : Nat) (state : Stage i) :
    Decoration.Over.stateChain (a := a) (advance := advance) rDeco (n + 1) i state =
      Decoration.Over.append (rDeco i state)
        (fun path =>
          Decoration.Over.stateChain (a := a) rDeco n (i + 1) (advance i state path))

theorem comp_time {f : α → β} {f' : β → γ}
    (h : EncPolyTime ea eb f) (h' : EncPolyTime eb ec f') :
    (h.comp h').time = h.time + h'.time.comp (1 + Polynomial.X + h.time)

theorem comp_time_eval {f : α → β} {f' : β → γ}
    (h : EncPolyTime ea eb f) (h' : EncPolyTime eb ec f') (k : ℕ) :
    (h.comp h').time.eval k = h.time.eval k + h'.time.eval (1 + k + h.time.eval k)

theorem size_comp {f : α → β} {f' : β → γ}
    (h : EncPolyTime ea eb f) (h' : EncPolyTime eb ec f') :
    (h.comp h').size = h.size + h'.size

private lemma mk₁_eq (input : List Bool) :
    (BiTape.mk₁ input : BiTape Bool) =
      ⟨(StackTape.mapSome input).head, ∅, (StackTape.mapSome input).tail⟩

private lemma snocPush_final (c : Bool) (input : List Bool) :
    snocPush (StackTape.cons (some c) ∅) input.reverse =
      StackTape.mapSome (input ++ [c])

lemma reflTransGen_normCfg_reverse (hdec : ∀ s, dec (emb s) = some s) {c : tm.Cfg}
    {c' : (reify (normTable tm emb dec)).Cfg}
    (h : Relation.ReflTransGen (reify (normTable tm emb dec)).TransitionRelation
      (normCfg tm emb dec c) c') :
    ∃ c₂, c' = normCfg tm emb dec c₂ ∧ Relation.ReflTransGen tm.TransitionRelation c c₂

private lemma bitape_head_tail_eq_mk₁ (t : List Symbol) :
    (⟨(StackTape.mapSome t).head, ∅, (StackTape.mapSome t).tail⟩ : BiTape Symbol) =
      .mk₁ t

private lemma clearComputer_clear_steps (l : List Symbol) :
    RelatesInSteps (clearComputer (Symbol := Symbol)).TransitionRelation
      ⟨some (), .mk₁ l⟩ ⟨some (), .nil⟩ l.length

private lemma constComputer_clear_steps (o : Symbol) (os l : List Symbol) :
    RelatesInSteps (constComputer o os).TransitionRelation
      ⟨some (.inl ()), .mk₁ l⟩ ⟨some (.inl ()), .nil⟩ l.length
